import * as T from './vendor/three.module.min.js';
const clamp=x=>Math.max(0,Math.min(1,x)),pulse=(t,d)=>Math.sin(Math.PI*clamp(t/d))**2;
// Pose targets only. Warnings, collision, attack windows and world positions are untouched.
export function enemyExpression(r,time=0){const phase=r.phase,t=Math.max(0,r.timer||0),p=clamp(t/Math.max(.001,r.duration||1)),kind=r.spec?.kind||r.kind||'ram',hurt=phase==='hurt'?pulse(t,.28):0,guard=(r.guardAge??9)<.3?pulse(r.guardAge,.3):0,wind=['windup','seedwindup','sporewindup'].includes(phase),recover=phase==='recover',breath=recover?Math.sin(t*7)*Math.exp(-t*1.8):0;
 const h=r.heading||0,hit=r.hitDirection||{x:-Math.sin(h),z:-Math.cos(h)},recoilX=(hit.x*Math.cos(h)-hit.z*Math.sin(h))*hurt*.065,recoilZ=(hit.x*Math.sin(h)+hit.z*Math.cos(h))*hurt*.065;return{recoilX,recoilZ,pitch:hurt*(kind==='ram'?-.11:kind==='seed'?-.065:.07)+guard*.035+(wind?(kind==='spore'?-.055:kind==='seed'?.035:-.045)*p:0)+breath*.025,roll:hurt*Math.sin(t*25)*.035,back:hurt*.065,capLift:kind==='spore'?(phase==='pulse'?Math.max(0,Math.sin(t*Math.PI*2/1.2))*.055:wind?p*.045:0):0,blink:phase==='watch'&&((time+(r.spec?.ordinal||0)*.8)%4.7)<.12,brace:wind?p:0,recover};
}
export function combatAdvice(kind,r){if(kind==='hit')return r.hp<=0?'Rival yields · the path is clearing.':'Clean hit · watch its next preparation.';if(r.spec.kind==='seed')return r.phase==='recover'||r.phase==='hurt'?'Armour faces you · cast from the side or back.':'Shell closed · dodge the slam, then circle behind.';if(r.spec.kind==='spore')return'Cap protected · jump the ring, then cast while it lowers.';return'Guarded · sidestep the charge, then cast during recovery.';}
export function reactionPose(kind,age,reduced=false){const d=kind==='hurt'?.48:kind==='blocked'?.4:.58,e=age>=0&&age<d?pulse(age,d):0,f=reduced?.25:1;return{body:(kind==='hurt'?-.055:kind==='blocked'?.022:-.012)*e*f,head:(kind==='hurt'?.055:kind==='blocked'?.035:Math.sin(age/d*Math.PI*2)*.045)*e*f,limb:(kind==='hurt'?.04:kind==='blocked'?-.02:.015)*e*f,done:age>=d};}
// Additive anatomical accents restore before the mixer; no root scaling or input lock.
export class CreatureExpression{
 constructor(model,profile=[],forwardYaw=0){this.model=model;this.parts=[];this.kind=null;this.age=9;this.applied=false;model.updateMatrixWorld(true);const axis=new T.Vector3(Math.cos(forwardYaw),0,-Math.sin(forwardYaw)).applyQuaternion(model.getWorldQuaternion(new T.Quaternion()));for(const p of profile)if(p.bone?.isBone){const a=axis.clone().applyQuaternion(p.bone.getWorldQuaternion(new T.Quaternion()).invert()).normalize();this.parts.push({...p,axis:a,base:new T.Quaternion()});}this.delta=new T.Quaternion();}
 cue(kind){this.kind=kind;this.age=0;}
 reset(){if(!this.applied)return;for(const p of this.parts)p.bone.quaternion.copy(p.base);this.applied=false;}
 update(dt,{enabled=true,attack=false,airborne=false,reduced=false}={}){this.reset();if(!enabled){this.kind=null;return;}this.age+=Math.max(0,dt);if(!this.kind||attack||airborne)return;const pose=reactionPose(this.kind,this.age,reduced);if(pose.done){this.kind=null;return;}for(const p of this.parts){p.base.copy(p.bone.quaternion);p.bone.quaternion.multiply(this.delta.setFromAxisAngle(p.axis,pose[p.role]||0));}this.applied=true;}
}
